def runs_bounded(g, target, bound):
    R,C=len(g),len(g[0])
    res=[[False]*C for _ in range(R)]
    for i in range(R):
        j=0
        while j<C:
            if g[i][j]==target:
                k=j
                while k<C and g[i][k]==target: k+=1
                left = j>0 and g[i][j-1]==bound
                right = k<C and g[i][k]==bound
                if left and right:
                    for t in range(j,k): res[i][t]=True
                j=k
            else: j+=1
    for j in range(C):
        i=0
        while i<R:
            if g[i][j]==target:
                k=i
                while k<R and g[k][j]==target: k+=1
                top = i>0 and g[i-1][j]==bound
                bot = k<R and g[k][j]==bound
                if top and bot:
                    for t in range(i,k): res[t][j]=True
                i=k
            else: i+=1
    return res

